```cpp
#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Create a string stream to hold the markdown text
    std::stringstream markdownStream(markdown);

    // Create a string stream to hold the HTML text
    std::stringstream htmlStream;

    // Write the markdown text to the HTML stream
    htmlStream << markdownStream;

    // Return the HTML text
    return htmlStream.str();
}

int main() {
    std::string markdown = "This is a markdown text.";
    std::string html = markdownToHtml(markdown);
    std::cout << "Markdown: " << markdown << std::endl;
    std::cout << "HTML: " << html << std::endl;
    return 0;
}
```

This function uses two `std::stringstream` objects to hold the markdown and HTML text, respectively. The markdown text is written to the HTML stream using the `<<` operator, and the resulting HTML text is returned using the `str()` method.

Note that this function assumes that the markdown text is well-formed. If the markdown text is not well-formed, the function may produce incorrect output.

